create table public.together_messages(id bigint generated always as identity primary key,match_id uuid not null references public.together_matches(id) on delete cascade,sender_id uuid not null references auth.users(id) on delete cascade,body text not null check(char_length(btrim(body)) between 1 and 1000),created_at timestamptz not null default now());
create index together_messages_match_created on public.together_messages(match_id,created_at);
create table public.together_blocks(blocker_id uuid not null references auth.users(id) on delete cascade,blocked_id uuid not null references auth.users(id) on delete cascade,created_at timestamptz not null default now(),primary key(blocker_id,blocked_id),check(blocker_id<>blocked_id));
create table public.together_reports(id bigint generated always as identity primary key,reporter_id uuid not null references auth.users(id) on delete cascade,reported_id uuid not null references auth.users(id) on delete cascade,reason text not null check(char_length(btrim(reason)) between 3 and 500),created_at timestamptz not null default now(),check(reporter_id<>reported_id));
alter table public.together_messages enable row level security;alter table public.together_blocks enable row level security;alter table public.together_reports enable row level security;
revoke all on public.together_messages,public.together_blocks,public.together_reports from public,anon,authenticated;

drop function public.together_discovery_cards(integer);
create function public.together_discovery_cards(p_limit integer default 20,p_city text default '',p_interest text default '') returns table(display_name text,city text,bio text,interests text[]) language sql security definer set search_path='' stable as $$
 select p.display_name,p.city,p.bio,p.interests from public.together_discovery_profiles p where auth.uid() is not null and p.visible and p.user_id<>auth.uid()
 and (btrim(p_city)='' or lower(p.city)=lower(btrim(p_city))) and (btrim(p_interest)='' or exists(select 1 from unnest(p.interests) i where lower(i)=lower(btrim(p_interest))))
 and not exists(select 1 from public.together_swipes s where s.actor_id=auth.uid() and s.target_id=p.user_id)
 and not exists(select 1 from public.together_blocks b where (b.blocker_id=auth.uid() and b.blocked_id=p.user_id) or (b.blocker_id=p.user_id and b.blocked_id=auth.uid())) order by p.updated_at desc limit least(greatest(coalesce(p_limit,20),1),50)$$;

drop function public.together_my_matches();
create function public.together_my_matches() returns table(match_id uuid,display_name text,city text,bio text,interests text[],matched_at timestamptz) language sql security definer set search_path='' stable as $$
 select m.id,p.display_name,p.city,p.bio,p.interests,m.created_at from public.together_matches m join public.together_discovery_profiles p on p.user_id=case when m.user_a=auth.uid() then m.user_b else m.user_a end where auth.uid() is not null and (m.user_a=auth.uid() or m.user_b=auth.uid()) and not exists(select 1 from public.together_blocks b where (b.blocker_id=m.user_a and b.blocked_id=m.user_b) or (b.blocker_id=m.user_b and b.blocked_id=m.user_a)) order by m.created_at desc$$;

create function public.together_match_messages(p_match_id uuid) returns table(id bigint,mine boolean,body text,created_at timestamptz) language sql security definer set search_path='' stable as $$select x.id,x.sender_id=auth.uid(),x.body,x.created_at from public.together_messages x join public.together_matches m on m.id=x.match_id where x.match_id=p_match_id and auth.uid() is not null and auth.uid() in(m.user_a,m.user_b) and not exists(select 1 from public.together_blocks b where (b.blocker_id=m.user_a and b.blocked_id=m.user_b) or (b.blocker_id=m.user_b and b.blocked_id=m.user_a)) order by x.created_at asc limit 200$$;
create function public.together_send_message(p_match_id uuid,p_body text) returns void language plpgsql security definer set search_path='' as $$declare m public.together_matches;begin if auth.uid() is null then raise exception 'authentication required' using errcode='42501';end if;select * into m from public.together_matches where id=p_match_id;if m.id is null or auth.uid() not in(m.user_a,m.user_b) then raise exception 'match unavailable' using errcode='42501';end if;if exists(select 1 from public.together_blocks b where (b.blocker_id=m.user_a and b.blocked_id=m.user_b) or (b.blocker_id=m.user_b and b.blocked_id=m.user_a)) then raise exception 'contact blocked' using errcode='42501';end if;insert into public.together_messages(match_id,sender_id,body) values(p_match_id,auth.uid(),btrim(p_body));end$$;
create function public.together_unmatch(p_match_id uuid) returns void language plpgsql security definer set search_path='' as $$begin delete from public.together_matches where id=p_match_id and auth.uid() in(user_a,user_b);if not found then raise exception 'match unavailable' using errcode='42501';end if;end$$;
create function public.together_block_person(p_display_name text) returns void language plpgsql security definer set search_path='' as $$declare t uuid;begin select user_id into t from public.together_discovery_profiles where lower(display_name)=lower(btrim(p_display_name)) and user_id<>auth.uid();if auth.uid() is null or t is null then raise exception 'person unavailable' using errcode='42501';end if;insert into public.together_blocks values(auth.uid(),t,now()) on conflict do nothing;delete from public.together_matches where least(user_a,user_b)=least(auth.uid(),t) and greatest(user_a,user_b)=greatest(auth.uid(),t);end$$;
create function public.together_report_person(p_display_name text,p_reason text) returns void language plpgsql security definer set search_path='' as $$declare t uuid;begin select user_id into t from public.together_discovery_profiles where lower(display_name)=lower(btrim(p_display_name)) and user_id<>auth.uid();if auth.uid() is null or t is null then raise exception 'person unavailable' using errcode='42501';end if;insert into public.together_reports(reporter_id,reported_id,reason) values(auth.uid(),t,btrim(p_reason));end$$;
revoke all on function public.together_discovery_cards(integer,text,text),public.together_my_matches(),public.together_match_messages(uuid),public.together_send_message(uuid,text),public.together_unmatch(uuid),public.together_block_person(text),public.together_report_person(text,text) from public,anon;
grant execute on function public.together_discovery_cards(integer,text,text),public.together_my_matches(),public.together_match_messages(uuid),public.together_send_message(uuid,text),public.together_unmatch(uuid),public.together_block_person(text),public.together_report_person(text,text) to authenticated;
